import pytest

from allocate import allocate


def test_weighted_three_way():
    assert sum(allocate(100, [1, 1, 4])) == 100


def test_weighted_uneven():
    assert sum(allocate(100, [2, 3, 7])) == 100


def test_weighted_two_way():
    assert sum(allocate(57, [1, 3])) == 57


def test_weighted_four_way():
    assert sum(allocate(1000, [1, 1, 1, 5])) == 1000


def test_equal_three_way_split():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]


@pytest.mark.parametrize(
    "total, weights, expected",
    [
        (100, [1, 1, 4], [17, 17, 66]),
        (100, [2, 3, 7], [17, 25, 58]),
        (2, [1, 1, 1], [1, 1, 0]),
        (1, [1, 3], [0, 1]),
        (100, [0, 1, 0, 2], [0, 33, 0, 67]),
        (12, [1, 2, 3], [2, 4, 6]),
        (0, [1, 2], [0, 0]),
        (57, [3], [57]),
        (-100, [1, 1, 1], [-33, -33, -34]),
        (-1, [0, 1, 3], [0, 0, -1]),
        (10**30 + 1, [1, 1], [5 * 10**29 + 1, 5 * 10**29]),
    ],
)
def test_largest_remainder(total, weights, expected):
    original = weights.copy()
    assert allocate(total, weights) == expected
    assert sum(expected) == total
    assert weights == original


