def test_conservation_and_share_bounds():
    from itertools import product

    for weights in product(range(4), repeat=3):
        denom = sum(weights)
        if not denom:
            continue
        for total in range(-20, 21):
            parts = allocate(total, list(weights))
            assert sum(parts) == total
            assert len(parts) == len(weights)
            for part, weight in zip(parts, weights):
                floor, remainder = divmod(total * weight, denom)
                assert floor <= part <= floor + bool(remainder)
                if weight == 0:
                    assert part == 0


